def heuristic(a, b, heuristic_type='euclidean'):
    """
    Compute the heuristic value between two points.
    """
    if heuristic_type == 'euclidean':
        return ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5
    elif heuristic_type == 'manhattan':
        return abs(a[0] - b[0]) + abs(a[1] - b[1])
    elif heuristic_type == 'chebyshev':
        return max(abs(a[0] - b[0]), abs(a[1] - b[1]))
    else:
        raise ValueError("Unknown heuristic type")

def a_star_search(graph, start, goal, heuristic_type='euclidean'):
    """
    A* search algorithm implementation.
    :param graph: The graph represented as a dictionary of nodes and their neighbors.
    :param start: The starting node.
    :param goal: The goal node.
    :param heuristic_type: The type of heuristic to use (default: 'euclidean').
    :return: A tuple (path, cost) or None if no path found.
