class Cell:
    def __init__(self, x, y, g_cost, h_cost, parent):
        self.x = x
        self.y = y
        self.g_cost = g_cost
        self.h_cost = h_cost
        self.total_cost = g_cost + h_cost
        self.parent = parent

    def __lt__(self, other):
        return self.total_cost < other.total_cost

def heuristic(a, b):
    return abs(a.x - b.x) + abs(a.y - b.y)

def astar_search(maze, start, end):
    rows, cols = len(maze), len(maze[0])

    open_set = []
    heapq.heappush(open_set, (0, Cell(start.x, start.y, 0, heuristic(start, end), None)))

    came_from = {}
    g_score = {cell: float('inf') for row in maze for cell in row}
    g_score[start] = 0

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == end:
            path = []
            while current:
                path.append((current.x, current.y))
                current = current.parent
            return path[::-1]  # Return the path in the correct order

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            x, y = current.x + dx, current.y + dy
            if 0 <= x < rows and 0 <= y < cols and maze[x][y] == 0 and g_score[(x, y)] == float('inf'):
